package org.secu3.android.models.packets.out.params

import org.junit.Assert.*
import org.junit.Test
import org.secu3.android.models.RawPacket
import org.secu3.android.ui.parameters.pages.compose.AdcNumber
import org.secu3.android.ui.parameters.pages.compose.setAdcValue

/** Golden words below follow Manager ControlApp/ParamsIO; they are not generated by pack(). */
class ParameterWireParityTest {
    private fun bytes(word: Int, count: Int) = IntArray(count) { (word ushr ((count - 1 - it) * 8)) and 255 }
    private fun adcFrame(mode: Boolean, factor: Int, correction: Int): IntArray =
        intArrayOf(64, 'r'.code, if (mode) 0xA1 else 0xA0) +
            (0 until 12).flatMap { (bytes(factor, 2) + bytes(correction, 4)).toList() }.toIntArray() +
            intArrayOf(0xAA, 0x55)

    @Test fun adcModeOffDoesNotMultiplyCorrectionsAndPreservesAllChannelsAndTail() {
        for ((word, value) in listOf(0x00322000 to .5f, 0xFFCE2000.toInt() to -.5f)) {
            val frame = adcFrame(false, 0x8000, word) // factor 2, correction +/- .5 V
            val packet = AdcCorrectionsParamPacket().parse(frame) as AdcCorrectionsParamPacket
            assertEquals(value, packet.mapAdcCorrection, .000001f)
            assertEquals(value, packet.ai8AdcCorrection, .000001f)
            assertArrayEquals(frame.drop(1).toIntArray(), packet.pack())
            packet.mapAdcFactor = 1.5f // changing a factor must not alter any correction word in this mode
            val packed = packet.pack()
            for (channel in 0 until 12) assertArrayEquals(bytes(word, 4), packed.sliceArray(4 + 6 * channel until 8 + 6 * channel))
            assertEquals(listOf(0xAA, 0x55), packed.takeLast(2))
        }
    }

    @Test fun adcModeOnUsesFactorAndUndefinedZeroChannelsRemainFiniteAndLossless() {
        val frame = adcFrame(true, 0x8000, 0x00642000) // factor 2, correction .5 V in multiply mode
        val packet = AdcCorrectionsParamPacket().parse(frame) as AdcCorrectionsParamPacket
        assertEquals(.5f, packet.ai8AdcCorrection, .000001f)
        assertArrayEquals(frame.drop(1).toIntArray(), packet.pack())
        val zero = adcFrame(true, 0, 0x12345678)
        val parsed = AdcCorrectionsParamPacket().parse(zero) as AdcCorrectionsParamPacket
        assertEquals(0f, parsed.tpsAdcCorrection, 0f)
        assertArrayEquals(zero.drop(1).toIntArray(), parsed.pack())
        parsed.setAdcValue(AdcNumber.MAP_FACTOR, 1f)
        val packed = parsed.pack()
        for (channel in 1 until 12) assertArrayEquals(bytes(0x12345678, 4), packed.sliceArray(4 + 6 * channel until 8 + 6 * channel))
        parsed.setAdcValue(AdcNumber.TPS_CORRECTION, .25f)
        assertArrayEquals(bytes(0x2000, 4), parsed.pack().sliceArray(22 until 26))
        val modeOffZero = AdcCorrectionsParamPacket().parse(adcFrame(false, 0, 0x00322000)) as AdcCorrectionsParamPacket
        assertEquals(.5f, modeOffZero.ai8AdcCorrection, .000001f)
        modeOffZero.pack() // must not throw on zero factors in disabled-compensation mode
    }

    @Test fun zeroFactorFallbackCannotReappearAfterModeOrFactorChanges() {
        val frame = adcFrame(true, 0, 0x12345678)
        val p = AdcCorrectionsParamPacket().parse(frame) as AdcCorrectionsParamPacket
        p.adcCompMode = false
        p.pack()
        p.adcCompMode = true
        assertArrayEquals(bytes(0x2000, 4), p.pack().sliceArray(4..7))
        val q = AdcCorrectionsParamPacket().parse(frame) as AdcCorrectionsParamPacket
        q.mapAdcFactor = 1f
        q.pack()
        q.mapAdcFactor = 0f
        assertArrayEquals(bytes(0x2000, 4), q.pack().sliceArray(4..7))
    }

    @Test fun tpsGradientMatchesSignedManagerWordsEvenWhenEditingAnotherField() {
        for (word in listOf(41, 0xFFD7)) { // round(+/- 1 * 128 * 128 * .0025)
            val frame = IntArray(49)
            frame[0] = 64; frame[1] = 'n'.code
            frame[18] = word ushr 8; frame[19] = word and 255
            val packet = FunSetParamPacket().parse(frame) as FunSetParamPacket
            packet.mapCurveOffset = .25f
            assertArrayEquals(bytes(word, 2), packet.pack().sliceArray(17..18))
        }
        assertArrayEquals(intArrayOf(0, 41), FunSetParamPacket(tpsCurveGradient = 1f).pack().sliceArray(17..18))
    }

    @Test fun tpsRawUsesSignedSixteenBitAdcVoltage() {
        for ((word, volts) in listOf(
            0xFFFF to -.0025f,
            0xFE70 to -1f,
            0x0000 to 0f,
            0x0190 to 1f,
            0x8000 to -81.92f,
        )) {
            val frame = IntArray(49)
            frame[0] = 64; frame[1] = 'n'.code
            frame[33] = word ushr 8; frame[34] = word and 255
            val packet = FunSetParamPacket().parse(frame) as FunSetParamPacket
            assertEquals("TPS raw word 0x${word.toString(16)}", volts, packet.tps_raw, .00001f)
        }
    }

    @Test fun apps1RawIsUnsignedReadOnlyAdcVoltageAndKnownWordIsNotSent() {
        for ((raw, volts) in listOf(400 to 1f, 0x8000 to 81.92f)) {
            val frame = IntArray(49)
            frame[0] = 64; frame[1] = 'n'.code
            frame[47] = raw ushr 8; frame[48] = raw and 255
            val packet = FunSetParamPacket().parse(frame) as FunSetParamPacket
            assertEquals(volts, packet.apps1Raw, .000001f)
            assertEquals(44, packet.pack().size) // descriptor plus 43-byte FUNSET payload
        }
    }

    @Test fun apps1RawRequiresFullKnownPayloadAndPreservesLaterExtension() {
        val shortFrame = IntArray(48).also { it[0] = 64; it[1] = 'n'.code }
        assertThrows(IllegalArgumentException::class.java) { FunSetParamPacket().parse(shortFrame) }

        val frame = IntArray(51).also {
            it[0] = 64; it[1] = 'n'.code
            it[47] = 0x01; it[48] = 0x90 // 400 ADC counts = 1 V
            it[49] = 0xCA; it[50] = 0xFE
        }
        val packet = FunSetParamPacket().parse(frame) as FunSetParamPacket
        assertEquals(1f, packet.apps1Raw, .000001f)
        assertArrayEquals(intArrayOf(0xCA, 0xFE), packet.pack().takeLast(2).toIntArray())
        assertEquals(46, packet.pack().size) // descriptor plus the preserved two-byte extension
    }

    @Test fun gasVoltageUnknownRawSixIsNotNormalizedToDisabledCodeFifteen() {
        assertEquals(6, FunSetParamPacket(gasVUni = 6).pack()[24])
        assertEquals(15, FunSetParamPacket(gasVUni = 15).pack()[24])
    }

    @Test fun minimumPulseUses1284DiscreteAndPreservesOtherBank() {
        val packet = InjctrParPacket()
        packet.minPw0 = 1f; packet.minPw1 = 2f
        assertArrayEquals(intArrayOf(78, 39), packet.pack().sliceArray(30..31))
        packet.minPw0 = 0f
        assertEquals(78, packet.pack()[30])
    }

    @Test fun starterPrimePulsesUse1284DiscreteForReadingAndWriting() {
        val frame = IntArray(23)
        frame[0] = 64; frame[1] = 'o'.code
        frame[9] = 0x03; frame[10] = 0xE8 // cold: raw 1000 ticks, indices follow STARTR_PAR
        frame[11] = 0x07; frame[12] = 0xD0 // hot: raw 2000 ticks
        val packet = RawPacket(frame + intArrayOf(0, 0)).parse(null) as StarterParamPacket
        assertEquals(3.2f, packet.injPrimeCold, .000001f)
        assertEquals(6.4f, packet.injPrimeHot, .000001f)
        assertArrayEquals(frame.drop(1).toIntArray(), packet.pack())
        packet.injPrimeCold = 10f
        assertArrayEquals(intArrayOf(12, 53), packet.pack().sliceArray(8..9))
    }

    @Test fun negativeHalfCountsFollowManagerRoundingAwayFromZero() {
        assertEquals(255, LtftParamPacket(min = -.09765625f).pack()[13])
        val tps = FunSetParamPacket(tpsCurveGradient = -.5f / 40.96f)
        assertArrayEquals(intArrayOf(255, 255), tps.pack().sliceArray(17..18))
        val adc = AdcCorrectionsParamPacket(mapAdcFactor = 1f, mapAdcCorrection = .00125f)
        assertArrayEquals(bytes(0x6000, 4), adc.pack().sliceArray(4..7))
    }

    @Test fun ltftNegativeLimitRoundsToSignedByteInsteadOfZero() {
        val packet = LtftParamPacket(min = -.1f)
        assertEquals(255, packet.pack()[13])
    }
}
